import com.kobil.wrapper.events.*

fun transactionRequest(): StartTransactionEvent = StartTransactionEvent()
fun confirmationResponse(request: DisplayConfirmationRequestEvent,
    userDecision: ConfirmationType): DisplayConfirmationEvent =
    DisplayConfirmationEvent(userDecision, request.transactionInformation)
fun terminalTransactionStatus(event: EventFrameworkEvent): StatusType? =
    (event as? TransactionEndEvent)?.status
// Display request.transactionInformation and request.timerValue first.
// Send only the actual user's decision; do not default to approval.
// DisplayConfirmationResultEvent is an acknowledgement, not a terminal result.

