import KSMasterController

func transactionRequest() -> KSMStartTransactionEvent { KSMStartTransactionEvent() }
func confirmationResponse(request: KSMDisplayConfirmationRequestEvent,
    userDecision: KSMConfirmationType) -> KSMDisplayConfirmationEvent {
    KSMDisplayConfirmationEvent(confirmationType: userDecision,
        andTransactionInformation: request.transactionInformation)
}
func terminalTransactionStatus(_ event: KsEvent) -> KSMEventStatusType? {
    (event as? KSMTransactionFinishedEvent)?.status
}
